// Tests for DetMath, the deterministic transcendental surface (OP/DetMath.double.cs). Each function
// is swept over its domain and compared to the Unity.Mathematics oracle within a few-ULP relative+
// absolute tolerance (DetMath is a deterministic polynomial approximation, not bit-identical to
// libm). Total/edge behavior (over/underflow, domain violations, non-finite inputs) is asserted
// explicitly. Everything runs under Burst FloatMode.Default (= Strict).
public class doubleDetMathTests
{
    [BurstCompile(CompileSynchronously = true, FloatPrecision = FloatPrecision.High, FloatMode = FloatMode.Default)]
    public struct TestsJob : IJob
    {
        public enum T
        {
            Exp, Exp2, Exp10, Log, Log2, Log10, Pow,
            Sin, Cos, SinCos, Tan, Asin, Acos, Atan, Atan2,
            Sinh, Cosh, Tanh, Acosh,
            ExpOverflow, ExpUnderflow, ExpPosInf, ExpNegInf, ExpNaN,
            LogEdges, TrigEdges, AtanEdges, PowEdges,
        }

        public T Type;

        // Type-scaled closeness: absorbs the few-ULP gap between DetMath and libm, and the absolute
        // form (1 + |expected|) keeps zero-crossings (sin/cos/atan) from inflating relative error.
        static void Close(double got, double expected)
        {
            
            
            const double tol = 1e-12;
            
            double diff = math.abs(got - expected);
            double scale = (double)1 + math.abs(expected);
            Assert.IsTrue(diff <= tol * scale);
        }

        public void Execute()
        {
            switch (Type)
            {
                case T.Exp:   Sweep(T.Exp,   (double)(-20), (double)20);  break;
                case T.Exp2:  Sweep(T.Exp2,  (double)(-20), (double)20);  break;
                case T.Exp10: Sweep(T.Exp10, (double)(-8),  (double)8);   break;
                case T.Log:   Sweep(T.Log,   (double)0.05,  (double)100); break;
                case T.Log2:  Sweep(T.Log2,  (double)0.05,  (double)100); break;
                case T.Log10: Sweep(T.Log10, (double)0.05,  (double)100); break;
                case T.Sin:   Sweep(T.Sin,   (double)(-10), (double)10);  break;
                case T.Cos:   Sweep(T.Cos,   (double)(-10), (double)10);  break;
                case T.SinCos:Sweep(T.SinCos,(double)(-10), (double)10);  break;
                case T.Tan:   Sweep(T.Tan,   (double)(-1.3), (double)1.3);break;   // stay off the poles
                case T.Asin:  Sweep(T.Asin,  (double)(-0.99),(double)0.99);break;
                case T.Acos:  Sweep(T.Acos,  (double)(-0.99),(double)0.99);break;
                case T.Atan:  Sweep(T.Atan,  (double)(-100),(double)100); break;
                case T.Sinh:  Sweep(T.Sinh,  (double)(-10), (double)10);  break;
                case T.Cosh:  Sweep(T.Cosh,  (double)(-10), (double)10);  break;
                case T.Tanh:  Sweep(T.Tanh,  (double)(-10), (double)10);  break;
                case T.Acosh: Sweep(T.Acosh, (double)1,     (double)20);  break;
                case T.Pow:   PowSweep();  break;
                case T.Atan2: Atan2Sweep(); break;
                case T.ExpOverflow:  Assert.IsTrue(DetMath.Exp((double)10000) == (double)float.PositiveInfinity); break;
                case T.ExpUnderflow: Assert.IsTrue(DetMath.Exp((double)(-10000)) == (double)0); break;
                case T.ExpPosInf:    Assert.IsTrue(DetMath.Exp((double)float.PositiveInfinity) == (double)float.PositiveInfinity); break;
                case T.ExpNegInf:    Assert.IsTrue(DetMath.Exp((double)float.NegativeInfinity) == (double)0); break;
                case T.ExpNaN:       { double en = DetMath.Exp((double)float.NaN); Assert.IsTrue(en != en); } break;
                case T.LogEdges:  LogEdges();  break;
                case T.TrigEdges: TrigEdges(); break;
                case T.AtanEdges: AtanEdges(); break;
                case T.PowEdges:  PowEdges();  break;
            }
        }

        void Sweep(T k, double lo, double hi)
        {
            const int N = 500;
            for (int i = 0; i <= N; i++)
            {
                double x = lo + (hi - lo) * ((double)i / (double)N);
                switch (k)
                {
                    case T.Exp:   Close(DetMath.Exp(x),   math.exp(x));   break;
                    case T.Exp2:  Close(DetMath.Exp2(x),  math.exp2(x));  break;
                    case T.Exp10: Close(DetMath.Exp10(x), math.exp10(x)); break;
                    case T.Log:   Close(DetMath.Log(x),   math.log(x));   break;
                    case T.Log2:  Close(DetMath.Log2(x),  math.log2(x));  break;
                    case T.Log10: Close(DetMath.Log10(x), math.log10(x)); break;
                    case T.Sin:   Close(DetMath.Sin(x),   math.sin(x));   break;
                    case T.Cos:   Close(DetMath.Cos(x),   math.cos(x));   break;
                    case T.SinCos:
                        DetMath.SinCos(x, out double s, out double c);
                        Close(s, math.sin(x)); Close(c, math.cos(x));
                        break;
                    case T.Tan:   Close(DetMath.Tan(x),   math.tan(x));   break;
                    case T.Asin:  Close(DetMath.Asin(x),  math.asin(x));  break;
                    case T.Acos:  Close(DetMath.Acos(x),  math.acos(x));  break;
                    case T.Atan:  Close(DetMath.Atan(x),  math.atan(x));  break;
                    case T.Sinh:  Close(DetMath.Sinh(x),  math.sinh(x));  break;
                    case T.Cosh:  Close(DetMath.Cosh(x),  math.cosh(x));  break;
                    case T.Tanh:  Close(DetMath.Tanh(x),  math.tanh(x));  break;
                    case T.Acosh: Close(DetMath.Acosh(x), math.log(x + math.sqrt(x * x - (double)1))); break;
                }
            }
        }

        void PowSweep()
        {
            const int N = 60;
            for (int i = 0; i <= N; i++)
            {
                double x = (double)0.1 + (double)9.9 * ((double)i / (double)N);
                for (int j = 0; j <= N; j++)
                {
                    double y = (double)(-3) + (double)6 * ((double)j / (double)N);
                    Close(DetMath.Pow(x, y), math.pow(x, y));
                }
            }
        }

        void Atan2Sweep()
        {
            const int N = 40;
            for (int i = 0; i <= N; i++)
            {
                double y = (double)(-5) + (double)10 * ((double)i / (double)N);
                for (int j = 0; j <= N; j++)
                {
                    double x = (double)(-5) + (double)10 * ((double)j / (double)N);
                    if (math.abs(x) < (double)0.05 && math.abs(y) < (double)0.05) continue;   // skip origin
                    Close(DetMath.Atan2(y, x), math.atan2(y, x));
                }
            }
        }

        void LogEdges()
        {
            double inf = (double)float.PositiveInfinity;
            double ninf = (double)float.NegativeInfinity;
            double nan = (double)float.NaN;
            Assert.IsTrue(DetMath.Log((double)0) == ninf);
            double ln = DetMath.Log((double)(-1)); Assert.IsTrue(ln != ln);
            Assert.IsTrue(DetMath.Log(inf) == inf);
            Assert.IsTrue(math.abs(DetMath.Log((double)1)) <= (double)1e-6);
            double lnan = DetMath.Log(nan); Assert.IsTrue(lnan != lnan);
        }

        void TrigEdges()
        {
            double inf = (double)float.PositiveInfinity;
            double nan = (double)float.NaN;
            double si = DetMath.Sin(inf); Assert.IsTrue(si != si);
            double ci = DetMath.Cos(inf); Assert.IsTrue(ci != ci);
            double sn = DetMath.Sin(nan); Assert.IsTrue(sn != sn);
        }

        void AtanEdges()
        {
            double inf = (double)float.PositiveInfinity;
            double ninf = (double)float.NegativeInfinity;
            Assert.IsTrue(math.abs(DetMath.Atan(inf) - (double)1.5707963267948966) <= (double)1e-5);
            Assert.IsTrue(math.abs(DetMath.Atan(ninf) + (double)1.5707963267948966) <= (double)1e-5);
        }

        void PowEdges()
        {
            Assert.IsTrue(DetMath.Pow((double)0, (double)2) == (double)0);
        }
    }

